import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors: vendor names are unique within a tenant", () => {
  test(
    "creating a vendor whose name differs only by case from an existing one returns 409 vendor_name_taken",
    { tag: "@VEN-03" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const existingName = uniqueName("Acme Freight");
      const created = await member.post("/api/vendors", {
        data: {
          name: existingName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      expect(created.status(), "seed the existing vendor").toBe(201);
      expect((await created.json()).name).toBe(existingName);

      const duplicateName = existingName.toLowerCase();
      expect(duplicateName).not.toBe(existingName);

      // Act
      const response = await member.post("/api/vendors", {
        data: {
          name: duplicateName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      expect(response.status()).toBe(409);
      const body = await response.json();
      expect(body.error.code).toBe("vendor_name_taken");
    },
  );
});
